     9	/** Utilitários de dinheiro: sempre 2 casas, arredondamento meio para o par. */
    10	public final class Money {
    11	    public static final BigDecimal ZERO = round(BigDecimal.ZERO);
    12	
    13	    private Money() {}
    14	
    15	    public static BigDecimal round(BigDecimal v) {
    16	        return v.setScale(2, RoundingMode.HALF_EVEN);
    17	    }
    18	
    19	    public static BigDecimal of(String v) {
    20	        return round(new BigDecimal(v));
    21	    }
    22	
    23	    /** Fração (ex.: 0.12) de um valor, já arredondada para centavos. */
    24	    public static BigDecimal fraction(BigDecimal base, String fraction) {
    25	        return round(base.multiply(new BigDecimal(fraction)));
    26	    }
    27	
    28	    /** Formato brasileiro: R$ 1.234,56 */
    29	    public static String brl(BigDecimal v) {
    30	        DecimalFormatSymbols s = new DecimalFormatSymbols(Locale.ROOT);
    31	        s.setDecimalSeparator(',');
    32	        s.setGroupingSeparator('.');
    33	        return "R$ " + new DecimalFormat("#,##0.00", s).format(round(v));
    34	    }
    35	}
