     6	/**
     7	 * Um plano de tarifa: cada plano decide como calcula o preço, quem pode usá-lo
     8	 * e quanto devolve no cancelamento. Para um plano novo, basta implementar esta
     9	 * interface e registrá-lo em {@link RatePlans}.
    10	 */
    11	public interface RatePlan {
    12	    String code();
    13	
    14	    /**
    15	     * Calcula soma das diárias e desconto, ou lança {@link ApiException#invalid}
    16	     * se as regras do plano não permitem esta reserva.
    17	     */
    18	    Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode);
    19	
    20	    /** Valor devolvido ao cancelar uma reserva com {@code amountPaid} pago. */
    21	    BigDecimal refund(BigDecimal amountPaid);
    22	
    23	    record Quote(BigDecimal subtotal, BigDecimal discount) {
    24	        public BigDecimal total() { return subtotal.subtract(discount); }
    25	    }
    26	}
