    10	import java.util.function.UnaryOperator;
    11	
    12	/** Planos de tarifa existentes e o registro por código. */
    13	public final class RatePlans {
    14	    private static final Map<String, RatePlan> REGISTRY = new LinkedHashMap<>();
    15	
    16	    static {
    17	        register(new Discounted("STANDARD", "0", 1, p -> p));
    18	        register(new Discounted("NON_REFUNDABLE", "0.15", 1, p -> Money.ZERO));
    19	        register(new Corporate());
    20	        register(new WeekendPackage());
    21	        register(new Discounted("LONG_STAY", "0.10", 7, p -> p));
    22	    }
    23	
    24	    private RatePlans() {}
    25	
    26	    private static void register(RatePlan plan) { REGISTRY.put(plan.code(), plan); }
    27	
    28	    public static RatePlan find(String code) { return REGISTRY.get(code); }
    29	
    30	    // ---- preço base ----
    31	
    32	    public static boolean isHighSeason(LocalDate night) {
    33	        Month m = night.getMonth();
    34	        if (m == Month.JANUARY || m == Month.FEBRUARY || m == Month.JULY) return true;
    35	        return m == Month.DECEMBER && night.getDayOfMonth() >= 15;
    36	    }
    37	
    38	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    39	        BigDecimal rate = room.nightlyRate();
    40	        return isHighSeason(night) ? Money.fraction(rate, "1.20") : Money.round(rate);
    41	    }
    42	
    43	    public static BigDecimal nightsSum(Room room, LocalDate in, LocalDate out) {
    44	        BigDecimal sum = Money.ZERO;
    45	        for (LocalDate d = in; d.isBefore(out); d = d.plusDays(1)) {
    46	            sum = sum.add(nightPrice(room, d));
    47	        }
    48	        return Money.round(sum);
    49	    }
    50	
    51	    // ---- planos ----
    52	
    53	    /** Diárias normais com um percentual de desconto, mínimo de noites e regra de devolução. */
    54	    static class Discounted implements RatePlan {
    55	        private final String code;
    56	        private final String discountFraction;
    57	        private final int minNights;
    58	        private final UnaryOperator<BigDecimal> refundRule;
    59	
    60	        Discounted(String code, String discountFraction, int minNights, UnaryOperator<BigDecimal> refundRule) {
    61	            this.code = code;
