 75	        });
 76	        return app;
 77	    }
 78	
 79	    // ---- criação ----
 80	
 81	    private static Reservation create(Hotel hotel, Context ctx) {
 82	        JsonNode body;
 83	        try {
 84	            body = JSON.readTree(ctx.bodyAsBytes());
 85	        } catch (Exception e) {
 86	            throw ApiException.invalid("Corpo da requisição não é um JSON válido");
 87	        }
 88	        if (body == null || !body.isObject()) throw ApiException.invalid("Corpo da requisição deve ser um objeto JSON");
 89	
 90	        JsonNode room = body.get("roomNumber");
 91	        if (room == null || !room.isInt()) throw ApiException.invalid("roomNumber é obrigatório");
 92	        String name = text(body, "guestName");
 93	        String email = text(body, "guestEmail");
 94	        String cpf = text(body, "guestCpf");
 95	        LocalDate in = date(body, "checkIn");
 96	        LocalDate out = date(body, "checkOut");
 97	        JsonNode g = body.get("guests");
 98	        if (g == null || !g.isInt()) throw ApiException.invalid("guests é obrigatório");
 99	        String planCode = text(body, "ratePlan");
100	        RatePlan plan = RatePlans.find(planCode);
101	        if (plan == null) throw ApiException.invalid("ratePlan desconhecido");
102	        if (!out.isAfter(in)) throw ApiException.invalid("A saída deve ser depois da entrada");
103	        if (g.asInt() < 1) throw ApiException.invalid("É preciso ao menos um hóspede");
104	
105	        JsonNode cc = body.get("companyCode");
106	        String companyCode = cc != null && cc.isTextual() ? cc.asText() : null;
107	        return hotel.create(room.asInt(), name, email, cpf, in, out, g.asInt(), plan, companyCode);
108	    }
109	
110	    private static String text(JsonNode body, String field) {
111	        JsonNode n = body.get(field);
112	        if (n == null || !n.isTextual() || n.asText().isBlank()) throw ApiException.invalid(field + " é obrigatório");
113	        return n.asText();
114	    }
115	
116	    private static LocalDate date(JsonNode body, String field) {
117	        try {
118	            return LocalDate.parse(text(body, field));
119	        } catch (DateTimeParseException e) {
120	            throw ApiException.invalid(field + " inválida (use AAAA-MM-DD)");
121	        }
122	    }
