132	        m.put("guestCpf", r.guestCpf);
133	        m.put("checkIn", r.checkIn.toString());
134	        m.put("checkOut", r.checkOut.toString());
135	        m.put("guests", r.guests);
136	        m.put("ratePlan", r.plan.code());
137	        m.put("nights", r.nights());
138	        m.put("subtotal", r.subtotal);
139	        m.put("discount", r.discount);
140	        m.put("total", r.total);
141	        m.put("status", r.status);
142	        m.put("amountPaid", r.amountPaid);
143	        m.put("refund", r.refund);
144	        return m;
145	    }
146	
147	    private static Map<String, Object> document(Reservation r) {
148	        Map<String, Object> m = new LinkedHashMap<>();
149	        m.put("title", "Comprovante de reserva");
150	        m.put("reservationId", r.id);
151	        m.put("guestName", r.guestName);
152	        m.put("guestCpf", r.guestCpf);
153	        m.put("roomNumber", r.room.number());
154	        m.put("roomType", r.room.type());
155	        m.put("checkIn", r.checkIn.toString());
156	        m.put("checkOut", r.checkOut.toString());
157	        m.put("nights", r.nights());
158	        m.put("subtotal", r.subtotal);
159	        m.put("discount", r.discount);
160	        m.put("total", r.total);
161	        return m;
162	    }
163	
164	    private static void error(Context ctx, int status, String code, String message) {
165	        Map<String, Object> m = new LinkedHashMap<>();
166	        m.put("error", code);
167	        m.put("message", message);
168	        json(ctx, status, m);
169	    }
170	
171	    private static void json(Context ctx, int status, Object body) {
172	        try {
173	            ctx.status(status).contentType("application/json").result(JSON.writeValueAsString(body));
174	        } catch (Exception e) {
175	            throw new IllegalStateException(e);
176	        }
177	    }
178	}
