185	public class Reservation {
186	    final int id;
187	    final Room room;
188	    final String guestName, guestEmail, guestCpf;
189	    final LocalDate checkIn, checkOut;
190	    final int guests;
191	    final RatePlan plan;
192	    final String companyCode;
193	    final BigDecimal subtotal, discount, total;
194	    ReservationStatus status = ReservationStatus.PENDING;
195	    BigDecimal amountPaid = Money.ZERO;
196	    BigDecimal refund; // null até cancelar
197	
198	    Reservation(int id, Room room, String guestName, String guestEmail, String guestCpf,
199	                LocalDate checkIn, LocalDate checkOut, int guests, RatePlan plan,
200	                String companyCode, RatePlan.Quote quote) {
201	        this.id = id;
202	        this.room = room;
203	        this.guestName = guestName;
204	        this.guestEmail = guestEmail;
205	        this.guestCpf = guestCpf;
206	        this.checkIn = checkIn;
207	        this.checkOut = checkOut;
208	        this.guests = guests;
209	        this.plan = plan;
210	        this.companyCode = companyCode;
211	        this.subtotal = quote.subtotal();
212	        this.discount = quote.discount();
213	        this.total = Money.round(quote.total());
214	    }
215	
216	    int nights() { return (int) ChronoUnit.DAYS.between(checkIn, checkOut); }
217	
218	    /** Dinheiro que ficou com a pousada. */
219	    BigDecimal netAmount() {
220	        return amountPaid.subtract(refund == null ? Money.ZERO : refund);
221	    }
222	
223	    boolean occupies(LocalDate night) {
224	        return !night.isBefore(checkIn) && night.isBefore(checkOut);
225	    }
