237	    public static final BigDecimal ZERO = round(BigDecimal.ZERO);
238	
239	    private Money() {}
240	
241	    public static BigDecimal round(BigDecimal v) {
242	        return v.setScale(2, RoundingMode.HALF_EVEN);
243	    }
244	
245	    public static BigDecimal of(String v) {
246	        return round(new BigDecimal(v));
247	    }
248	
249	    /** Fração (ex.: 0.12) de um valor, já arredondada para centavos. */
250	    public static BigDecimal fraction(BigDecimal base, String fraction) {
251	        return round(base.multiply(new BigDecimal(fraction)));
252	    }
253	
254	    /** Formato brasileiro: R$ 1.234,56 */
255	    public static String brl(BigDecimal v) {
256	        DecimalFormatSymbols s = new DecimalFormatSymbols(Locale.ROOT);
257	        s.setDecimalSeparator(',');
258	        s.setGroupingSeparator('.');
259	        return "R$ " + new DecimalFormat("#,##0.00", s).format(round(v));
260	    }
